import type { PluginContainerData } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';

export const COLLAPSIBLE_LIST_TYPE = 'wix-rich-content-plugin-collapsible-list';

export interface CollapsibleListPluginEditorConfig {
  type: 'collapsibleList';
  isQapageData?: boolean;
}

export interface CollapsibleListPluginViewerConfig {}

// took from proto definition -
// https://github.com/wix-private/ricos/blob/master/packages/wix-ricos-schema/src/main/proto/wix/rich_content/v1/plugin_collapsible_list.proto
export type CollapsibleListComponentData = {
  containerData: PluginContainerData;
  expandOnlyOne: boolean;
  initialExpandedItems: InitialExpandedItems;
  direction?: ListDirection;
  isQapageData?: boolean;
};

export const initialExpandedItems = {
  FIRST: 'FIRST',
  ALL: 'ALL',
  NONE: 'NONE',
} as const;

export type InitialExpandedItems = (typeof initialExpandedItems)[keyof typeof initialExpandedItems];

export const listDirection = {
  LTR: 'LTR',
  RTL: 'RTL',
} as const;

export type ListDirection = (typeof listDirection)[keyof typeof listDirection];
