import {
  TIPTAP_COLLAPSIBLE_ITEM_BODY_TYPE,
  TIPTAP_COLLAPSIBLE_ITEM_TITLE_TYPE,
  TIPTAP_COLLAPSIBLE_ITEM_TYPE,
  TIPTAP_COLLAPSIBLE_LIST_TYPE,
} from './../../ricos-content/index.js';
import { findParentNodeClosestToPos } from './../../tiptap/index.js';
import type { Editor } from './../../tiptap/core/index.js';
import { NodeSelection } from './../../tiptap/pm/state.js';

const jumpToCollapsibleTitle = (editor: $TSFixMe, collapsibleItemBody: $TSFixMe) => {
  if (!collapsibleItemBody) {
    return false;
  }
  editor
    .chain()
    .setTextSelection(collapsibleItemBody.pos - 2)
    .focus()
    .run();
  return true;
};

const getCollapsibleItemBody = (editor: Editor) =>
  findParentNodeClosestToPos(
    editor.state.selection.$from,
    node => node.type.name === TIPTAP_COLLAPSIBLE_ITEM_BODY_TYPE
  );

const getCollapsibleItemTitle = (editor: Editor) =>
  findParentNodeClosestToPos(
    editor.state.selection.$from,
    node => node.type.name === TIPTAP_COLLAPSIBLE_ITEM_TITLE_TYPE
  );

const getCollapsibleItem = (editor: Editor) =>
  findParentNodeClosestToPos(
    editor.state.selection.$from,
    node => node.type.name === TIPTAP_COLLAPSIBLE_ITEM_TYPE
  );

/** Handles all Backspace cases inside a collapsible list.
 *  Used by the plugin-level createShortcut so it runs before Tiptap's
 *  built-in joinBackward which would otherwise lift paragraphs out
 *  of the collapsible structure. */
export const handleCollapsibleBackspace = (
  editor: Editor,
  event?: KeyboardEvent
): 'handled' | 'continue' => {
  const { selection } = editor.state;

  // NodeSelection on COLLAPSIBLE_ITEM → delete the item
  if (
    selection instanceof NodeSelection &&
    selection.node.type.name === TIPTAP_COLLAPSIBLE_ITEM_TYPE
  ) {
    const $pos = editor.state.doc.resolve(selection.from);
    const parentList = findParentNodeClosestToPos(
      $pos,
      node => node.type.name === TIPTAP_COLLAPSIBLE_LIST_TYPE
    );
    if (parentList && parentList.node.childCount <= 1) {
      editor
        .chain()
        .deleteRange({
          from: parentList.pos,
          to: parentList.pos + parentList.node.nodeSize,
        })
        .focus()
        .run();
      event?.preventDefault();
      event?.stopImmediatePropagation();
      return 'handled';
    }
    const { from, to } = selection;
    editor.chain().deleteRange({ from, to }).focus().run();
    event?.preventDefault();
    event?.stopImmediatePropagation();
    return 'handled';
  }

  if (!selection.empty) {
    return 'continue';
  }

  // Backspace at body start → jump to title end
  const collapsibleItemBody = getCollapsibleItemBody(editor);
  const isAtBodyStart = selection.from - 1 === collapsibleItemBody?.start;
  if (isAtBodyStart) {
    jumpToCollapsibleTitle(editor, collapsibleItemBody);
    event?.preventDefault();
    event?.stopImmediatePropagation();
    return 'handled';
  }

  // Backspace at title start → NodeSelection on COLLAPSIBLE_ITEM
  const titleNode = getCollapsibleItemTitle(editor);
  const isAtTitleStart = selection.from - 1 === titleNode?.start;
  if (isAtTitleStart) {
    const collapsibleItem = getCollapsibleItem(editor);
    if (!collapsibleItem) {
      return 'continue';
    }
    editor.commands.setNodeSelection(collapsibleItem.pos);
    event?.preventDefault();
    event?.stopImmediatePropagation();
    return 'handled';
  }

  return 'continue';
};
