import { Dropdown } from '@wix/wix-ui-icons-common/lazy';

import type { AddButtonsCreator } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { INSERT_COLLAPSIBLE_LIST_BUTTON } from './data-hooks.js';
import { defaultCollapsibleList } from './tiptap/defaults.js';
import { COLLAPSIBLE_LIST_TYPE } from './types.js';

export const toolbarsToAddIn: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
  TOOLBARS.MOBILE,
];

export const getAddButtons: AddButtonsCreator = () => {
  return [
    {
      id: Node_Type.COLLAPSIBLE_LIST,
      icon: Dropdown,
      label: INSERT_PLUGIN_BUTTONS.COLLAPSIBLE_LIST,
      dataHook: INSERT_COLLAPSIBLE_LIST_BUTTON,
      tooltip: 'CollapsibleListPlugin_InsertButton_Tooltip',
      toolbars: toolbarsToAddIn,
      command: ({ publicCommands }) => {
        publicCommands.insertBlockWithBlankLines(COLLAPSIBLE_LIST_TYPE, defaultCollapsibleList, {
          updateSelection: 'text',
        });
        return true;
      },
      menuConfig: {
        tags: 'CollapsibleList_plugin_search_tags',
        group: 'advanced',
      },
    },
  ];
};
