import type { FC, ReactChild } from 'react';
import React from 'react';

type CollapsibleListContextProps = {
  isExpanded: (id: string) => boolean;
  toggle: (id: string) => void;
  children: ReactChild;
};

type ContextType = {
  isExpanded: (id: string) => boolean;
  toggle: (id: string) => void;
};

export const CollapsibleListContext = React.createContext<ContextType>(
  null as unknown as ContextType
);

export const CollapsibleListContextProvider: FC<CollapsibleListContextProps> = ({
  isExpanded,
  toggle,
  children,
}) => {
  return (
    <CollapsibleListContext.Provider value={{ isExpanded, toggle }}>
      {children}
    </CollapsibleListContext.Provider>
  );
};
