import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { CollapsibleListPluginViewerConfig } from './types.js';
import { COLLAPSIBLE_LIST_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export const pluginCollapsibleList: ViewerPluginCreator<
  CollapsibleListPluginViewerConfig
> = config => {
  return {
    config: { ...DEFAULTS.config, ...config },
    type: COLLAPSIBLE_LIST_TYPE,
    nodeViewRenderers,
  };
};
